const items = $input.all();

let cleanedData = [];
let uniqueKeys = new Set();

let totalRowsImported = items.length;
let rowsRemovedEmptyInvalid = 0;
let duplicateRowsRemoved = 0;
let invalidEmailsRemoved = 0;
let invalidPhonesRemoved = 0;

let customerCounter = 1;

for (let item of items) {
    let json = item.json;

    if (!json["Full Name"] && !json["Email"] && !json["Phone"]) {
        rowsRemovedEmptyInvalid++;
        continue;
    }

    let name = json["Full Name"] ? json["Full Name"].toString().replace(/\s+/g, ' ').trim() : '';
    let email = json["Email"] ? json["Email"].toString().trim().toLowerCase() : ''; // Case-insensitive checking
    let phone = json["Phone"] ? json["Phone"].toString().trim() : '';
    let city = json["City"] ? json["City"].toString().replace(/\s+/g, ' ').trim() : '';
    let regDate = json["Registration Date"] ? json["Registration Date"].toString().trim() : '';

    if (!name || !email || !phone) {
        rowsRemovedEmptyInvalid++;
        continue;
    }

    name = name.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
    city = city.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());

    // Strict Email Validation to allow ONLY valid user@gmail.com formats
    const gmailRegex = /^[a-zA-Z0-9._%+-]+@gmail\.com$/;
    if (!gmailRegex.test(email)) {
        invalidEmailsRemoved++;
        continue; 
    }

    let cleanPhone = phone.replace(/\D/g, ''); 
    if (cleanPhone.length === 10 && cleanPhone.startsWith('1')) {
        cleanPhone = '0' + cleanPhone;
    }

    if (!(cleanPhone.length === 11 && cleanPhone.startsWith('01'))) {
        invalidPhonesRemoved++;
        continue; 
    }

    let formattedDate = regDate;
    try {
        if (!isNaN(regDate) && Number(regDate) > 30000) {
            let excelEpoch = new Date(1899, 11, 30);
            let parsedDate = new Date(excelEpoch.getTime() + Number(regDate) * 24 * 60 * 60 * 1000);
            let year = parsedDate.getFullYear();
            let month = String(parsedDate.getMonth() + 1).padStart(2, '0');
            let day = String(parsedDate.getDate()).padStart(2, '0');
            formattedDate = `${year}-${month}-${day}`;
        } else {
            let parsedDate = new Date(regDate);
            if (!isNaN(parsedDate.getTime())) {
                let year = parsedDate.getFullYear();
                let month = String(parsedDate.getMonth() + 1).padStart(2, '0');
                let day = String(parsedDate.getDate()).padStart(2, '0');
                formattedDate = `${year}-${month}-${day}`;
            } else {
                formattedDate = new Date(Date.parse(regDate)).toISOString().split('T')[0];
            }
        }
    } catch (e) {
        formattedDate = "Invalid Date";
    }

    let duplicateKeyEmail = `email:${email}`;
    let duplicateKeyPhone = `phone:${cleanPhone}`;

    if (uniqueKeys.has(duplicateKeyEmail) || uniqueKeys.has(duplicateKeyPhone)) {
        duplicateRowsRemoved++;
        continue; 
    }
    uniqueKeys.add(duplicateKeyEmail);
    uniqueKeys.add(duplicateKeyPhone);

    let customerId = `CUST-${String(customerCounter).padStart(4, '0')}`;
    customerCounter++;

    cleanedData.push({
        json: {
            "Customer ID": customerId,
            "Full Name": name,
            "Email": email,
            "Phone": cleanPhone,
            "City": city,
            "Registration Date": formattedDate
        }
    });
}

console.log("--- SUMMARY REPORT ---");
console.log("Total Rows Imported:", totalRowsImported);
console.log("Empty/Missing Rows Removed:", rowsRemovedEmptyInvalid);
console.log("Duplicate Rows Removed:", duplicateRowsRemoved);
console.log("Invalid Emails Removed:", invalidEmailsRemoved);
console.log("Invalid Phones Removed:", invalidPhonesRemoved);
console.log("Final Row Count:", cleanedData.length);

return cleanedData;
